import{_ as e,o as l,c as n,a6 as s}from"./chunks/framework.BlDtR6jM.js";const u=JSON.parse('{"title":"数据与配置管线 (Data & Configuration Pipeline)","description":"","frontmatter":{"readingTime":"9 min read"},"headers":[],"relativePath":"项目实践/JRPG/00_项目概要/03_数据与配置管线.md","filePath":"项目实践/JRPG/00_项目概要/03_数据与配置管线.md"}'),o={name:"项目实践/JRPG/00_项目概要/03_数据与配置管线.md"};function a(i,t,r,g,d,c){return l(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="数据与配置管线-data-configuration-pipeline" tabindex="-1">数据与配置管线 (Data &amp; Configuration Pipeline) <a class="header-anchor" href="#数据与配置管线-data-configuration-pipeline" aria-label="Permalink to &quot;数据与配置管线 (Data &amp; Configuration Pipeline)&quot;">​</a></h1><blockquote><p><strong>核心原则</strong>：工具服务于内容。不同的数据类型需要不同的生产管线，切忌“一把梭”。 <strong>管线分层</strong>：静态数据用表 (Excel)，流程数据用图 (Graph)，复杂逻辑用代码 (Lua/C#)。</p></blockquote><h2 id="_1-技术选型决策-tech-stack-decision" tabindex="-1">1. 技术选型决策 (Tech Stack Decision) <a class="header-anchor" href="#_1-技术选型决策-tech-stack-decision" aria-label="Permalink to &quot;1. 技术选型决策 (Tech Stack Decision)&quot;">​</a></h2><p>针对 JRPG 复杂的剧情、任务和演出需求，我们采用 <strong>“分层混合架构”</strong>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">数据类型</th><th style="text-align:left;">特征描述</th><th style="text-align:left;">推荐工具/管线</th><th style="text-align:left;">输出格式</th><th style="text-align:left;">适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>静态数值</strong> (Static Data)</td><td style="text-align:left;">结构化、量大、扁平、需批量调整</td><td style="text-align:left;"><strong>Excel</strong> + 导表工具</td><td style="text-align:left;">JSON / Binary / ScriptableObject</td><td style="text-align:left;">物品表、怪物属性、升级经验、掉落表</td></tr><tr><td style="text-align:left;"><strong>剧情流程</strong> (Narrative Flow)</td><td style="text-align:left;">非线性、分支跳转、状态管理</td><td style="text-align:left;"><strong>Node Graph Editor</strong> (可视化节点)</td><td style="text-align:left;">JSON / Asset</td><td style="text-align:left;">任务流程、对话树、AI行为树</td></tr><tr><td style="text-align:left;"><strong>演出动画</strong> (Cinematics)</td><td style="text-align:left;">线性、时间轴精确控制、多轨并行</td><td style="text-align:left;"><strong>Unity Timeline</strong> / Sequence</td><td style="text-align:left;">PlayableAsset</td><td style="text-align:left;">过场动画、技能演出、镜头运镜</td></tr><tr><td style="text-align:left;"><strong>复杂逻辑</strong> (Complex Logic)</td><td style="text-align:left;">条件判断、公式计算、动态交互</td><td style="text-align:left;"><strong>xLua</strong> / C# Expressions</td><td style="text-align:left;">.lua / Delegate</td><td style="text-align:left;">伤害公式、特殊关卡机制、复杂任务条件</td></tr></tbody></table><h3 id="_1-1-可视化编辑器对比-articy-vs-unity插件" tabindex="-1">1.1 可视化编辑器对比：Articy vs Unity插件 <a class="header-anchor" href="#_1-1-可视化编辑器对比-articy-vs-unity插件" aria-label="Permalink to &quot;1.1 可视化编辑器对比：Articy vs Unity插件&quot;">​</a></h3><p>针对剧情与任务流程的可视化编辑，主要有“外部专业软件”与“引擎内插件”两种选择。</p><table tabindex="0"><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">代表工具</th><th style="text-align:left;">优势 (Pros)</th><th style="text-align:left;">劣势 (Cons)</th><th style="text-align:left;">适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>外部专业软件</strong></td><td style="text-align:left;"><strong>Articy:draft 3</strong></td><td style="text-align:left;">• <strong>编剧专用</strong>：数据库结构强大，适合纯文本/剧情管理。<br>• <strong>无关引擎</strong>：编剧不需要开Unity。<br>• <strong>全局视图</strong>：极其强大的大纲与流程管理。</td><td style="text-align:left;">• <strong>工作流割裂</strong>：需要导入导出，迭代不如引擎内即时。<br>• <strong>成本</strong>：商业软件，价格较高。<br>• <strong>集成</strong>：需要编写专门的解析层或使用插件。</td><td style="text-align:left;">文本量巨大、有专职编剧、剧情结构极其复杂的项目（如《极乐迪斯科》）。</td></tr><tr><td style="text-align:left;"><strong>Unity 全能插件</strong></td><td style="text-align:left;"><strong>Dialogue System for Unity</strong></td><td style="text-align:left;">• <strong>开箱即用</strong>：自带UI、任务系统、存档、Lua环境。<br>• <strong>生态丰富</strong>：支持Articy导入，支持各类RPG插件。<br>• <strong>引擎内嵌</strong>：修改即运行，无需导出。</td><td style="text-align:left;">• <strong>臃肿</strong>：功能极其繁杂，学习成本高。<br>• <strong>定制难</strong>：由于封装太深，修改底层逻辑较麻烦。</td><td style="text-align:left;">希望快速搭建标准JRPG对话与任务系统，不想造轮子。</td></tr><tr><td style="text-align:left;"><strong>Unity 轻量插件</strong></td><td style="text-align:left;"><strong>NodeCanvas</strong> / <strong>FlowCanvas</strong></td><td style="text-align:left;">• <strong>逻辑清晰</strong>：优秀的FSM/行为树编辑器，可视化体验极佳。<br>• <strong>性能好</strong>：代码结构干净，易于扩展。</td><td style="text-align:left;">• <strong>侧重AI</strong>：主要用于AI逻辑，对话功能相对较弱（需配合Dialogue Tree）。</td><td style="text-align:left;">既需要复杂的AI行为，又需要简单的对话交互。</td></tr><tr><td style="text-align:left;"><strong>自研/开源方案</strong></td><td style="text-align:left;"><strong>xNode</strong> / <strong>GraphView</strong></td><td style="text-align:left;">• <strong>完全掌控</strong>：数据结构完全贴合项目需求。<br>• <strong>轻量</strong>：没有多余功能，包体小。</td><td style="text-align:left;">• <strong>开发成本</strong>：需要自己写编辑器代码、数据解析器和运行时Runner。</td><td style="text-align:left;">有较强程序能力，且现成插件无法满足特定需求。</td></tr></tbody></table><blockquote><p><strong>💡 建议</strong>：</p><ul><li>如果你已经熟悉 <strong>Articy:draft 3</strong>，它可以作为“剧本源头”，配合 <strong>Dialogue System for Unity</strong> (作为Articy的运行时播放器) 是黄金搭档。</li><li>如果不想引入外部软件，且追求开发效率，直接使用 <strong>Dialogue System for Unity</strong> 是最稳妥的方案。</li><li>如果只是简单的分支对话，不需要复杂的数据库管理，<strong>xNode</strong> 自写一个简单工具最轻便。</li></ul></blockquote><hr><h2 id="_2-详细管线说明" tabindex="-1">2. 详细管线说明 <a class="header-anchor" href="#_2-详细管线说明" aria-label="Permalink to &quot;2. 详细管线说明&quot;">​</a></h2><h3 id="_2-1-剧情与任务-可视化为主-脚本为辅" tabindex="-1">2.1 剧情与任务：可视化为主，脚本为辅 <a class="header-anchor" href="#_2-1-剧情与任务-可视化为主-脚本为辅" aria-label="Permalink to &quot;2.1 剧情与任务：可视化为主，脚本为辅&quot;">​</a></h3><p><strong>Q: 为什么不用纯脚本 (xLua) 写剧情？</strong></p><ul><li><strong>可读性差</strong>：几千行的 <code>if-else</code> 和回调嵌套难以维护，无法一眼看出剧情分支全貌。</li><li><strong>调试困难</strong>：无法在运行时直观看到当前走到哪个节点。</li><li><strong>非程序友好</strong>：策划和编剧难以直接上手修改。</li></ul><p><strong>✅ 推荐方案：节点图 (Flow Graph) + 嵌入式脚本</strong></p><ul><li><strong>宏观流程 (Macro Flow)</strong>：使用 <strong>节点编辑器</strong> (如 xNode/GraphView)。 <ul><li><strong>Start Node</strong>: 任务开始</li><li><strong>Dialogue Node</strong>: 播放对话 ID: 1001</li><li><strong>Branch Node</strong>: 分支选择（接受/拒绝）</li><li><strong>Action Node</strong>: 发放奖励</li></ul></li><li><strong>微观逻辑 (Micro Logic)</strong>：在节点的“条件”或“执行”字段中填入简短的 <strong>Lua/C# 表达式</strong>。</li></ul><p><strong>示例：一个“需要等级&gt;10且持有信物”才能触发的对话节点</strong></p><ul><li><strong>节点类型</strong>: <code>ConditionNode</code></li><li><strong>可视化连接</strong>: 上连 <code>Start</code>，下连 <code>Dialogue</code></li><li><strong>节点配置</strong>: <ul><li><code>Condition Type</code>: Lua Expression</li><li><code>Script</code>: <code>return User.Level &gt; 10 and Bag.HasItem(1001)</code></li></ul></li></ul><h3 id="_2-2-演出与镜头-timeline-统治" tabindex="-1">2.2 演出与镜头：Timeline 统治 <a class="header-anchor" href="#_2-2-演出与镜头-timeline-统治" aria-label="Permalink to &quot;2.2 演出与镜头：Timeline 统治&quot;">​</a></h3><p><strong>Q: 剧情演出能用代码写吗？</strong></p><ul><li><strong>❌ 极其痛苦</strong>：用代码写 <code>Move(3s) -&gt; Wait(1s) -&gt; CameraPan(2s)</code> 需要反复运行调整，无法实时预览。</li><li><strong>✅ Timeline 优势</strong>：拖拽式调整时间轴，所见即所得。</li></ul><p><strong>管线集成</strong>：</p><ol><li>剧情节点图中有一个 <code>Timeline Node</code>。</li><li>运行到该节点时，加载并播放对应的 <code>.playable</code> 资源。</li><li>Timeline 播放结束，发送信号 (Signal) 回节点图，继续执行后续逻辑。</li></ol><h3 id="_2-3-静态配置-excel-的统治力" tabindex="-1">2.3 静态配置：Excel 的统治力 <a class="header-anchor" href="#_2-3-静态配置-excel-的统治力" aria-label="Permalink to &quot;2.3 静态配置：Excel 的统治力&quot;">​</a></h3><p>对于物品、怪物等数据，Excel 是不可替代的。</p><ul><li><strong>公式支持</strong>：数值策划可以直接在 Excel 用公式拉数值曲线。</li><li><strong>批量编辑</strong>：一键修改所有“火属性”怪物的抗性。</li><li><strong>工具链</strong>： <ul><li><code>Source</code>: <code>Design/Excels/Items.xlsx</code></li><li><code>Tool</code>: <code>ExcelExporter.exe</code></li><li><code>Runtime</code>: <code>Resources/Data/Json/Items.json</code> + <code>Dictionary&lt;int, ItemData&gt;</code></li></ul></li></ul><hr><h2 id="_3-综合案例-从-接任务-到-进副本" tabindex="-1">3. 综合案例：从“接任务”到“进副本” <a class="header-anchor" href="#_3-综合案例-从-接任务-到-进副本" aria-label="Permalink to &quot;3. 综合案例：从“接任务”到“进副本”&quot;">​</a></h2><p>假设流程：玩家与 NPC 对话 -&gt; 接受任务（需等级5） -&gt; 播放一段过场 -&gt; 开启副本传送门。</p><h3 id="步骤拆解" tabindex="-1">步骤拆解 <a class="header-anchor" href="#步骤拆解" aria-label="Permalink to &quot;步骤拆解&quot;">​</a></h3><ol><li><p><strong>触发器 (Trigger)</strong>:</p><ul><li>场景中 NPC 挂载 <code>Interactable</code> 组件。</li><li>点击 NPC，触发 <code>FlowGraphRunner</code>，加载 <code>Quest_01_Start.graph</code>。</li></ul></li><li><p><strong>流程图 (Graph) 执行</strong>:</p><ul><li><strong>Node 1 (Check)</strong>: 检查条件 <code>return User.Level &gt;= 5</code>。 <ul><li><em>Fail</em>: 跳转到 Node 2 (Dialogue: &quot;你还太弱了&quot;)。</li><li><em>Pass</em>: 跳转到 Node 3 (Dialogue: &quot;勇士，请帮帮我&quot;)。</li></ul></li><li><strong>Node 3 (Dialogue)</strong>: 显示对话 UI，等待玩家点击。</li><li><strong>Node 4 (Choice)</strong>: 选项 [接受] / [拒绝]。 <ul><li><em>接受</em>: 跳转 Node 5。</li></ul></li><li><strong>Node 5 (Timeline)</strong>: 播放 <code>Timeline_OpenGate</code>。 <ul><li><em>底层</em>: 隐藏 UI，相机移向大门，播放粒子特效，相机移回。</li></ul></li><li><strong>Node 6 (Action)</strong>: <ul><li>Lua: <code>QuestSystem.Accept(101)</code></li><li>Lua: <code>Map.EnablePortal(&quot;Dungeon_01&quot;)</code></li></ul></li></ul></li></ol><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><ul><li><strong>Excel</strong>: 定义了 任务ID(101) 的奖励、名字；定义了 传送门ID 的位置。</li><li><strong>Graph</strong>: 串联了 检查 -&gt; 对话 -&gt; 选择 -&gt; 演出 -&gt; 结果 的全流程。</li><li><strong>Timeline</strong>: 负责了 那几秒钟的 镜头和特效表演。</li><li><strong>Lua</strong>: 处理了 <code>User.Level &gt;= 5</code> 这种具体的判断逻辑。</li></ul><hr><h2 id="_4-目录结构规划" tabindex="-1">4. 目录结构规划 <a class="header-anchor" href="#_4-目录结构规划" aria-label="Permalink to &quot;4. 目录结构规划&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Assets/</span></span>
<span class="line"><span>├── Design/                 # 策划源文件 (不进包)</span></span>
<span class="line"><span>│   ├── Excels/             # Excel 配置表</span></span>
<span class="line"><span>│   └── Graphs/             # 节点图源文件</span></span>
<span class="line"><span>├── GameData/               # 生成的运行时数据</span></span>
<span class="line"><span>│   ├── Tables/             # JSON/Bytes</span></span>
<span class="line"><span>│   └── Flows/              # 序列化后的流程图数据</span></span>
<span class="line"><span>├── StreamingAssets/</span></span>
<span class="line"><span>│   └── Lua/                # Lua 脚本逻辑</span></span>
<span class="line"><span>└── Timelines/              # 演出资源</span></span></code></pre></div>`,36)])])}const h=e(o,[["render",a]]);export{u as __pageData,h as default};
